import {STYLE_PACKS,STYLE_DOMAINS} from './style-packs.js';
import {seedHash} from './resolver-v1.js';

const clone=value=>structuredClone(value);
const norm=value=>String(value||'').trim().toLowerCase();
const unique=(items,existing=[])=>{const seen=new Set(existing.map(norm));return items.filter(item=>{const key=norm(item.label||item);if(!key||seen.has(key))return false;seen.add(key);return true})};
const pick=(items,seed,offset=0)=>items.slice().sort((a,b)=>seedHash(`${seed}|${offset}|${a.id||a.label||a}`)-seedHash(`${seed}|${offset}|${b.id||b.label||b}`));

const INTERESTS=[
  {id:'creative-coding',label:'Creative coding',tags:['technology','creative']},{id:'field-recording',label:'Field recording',tags:['music','outdoors']},{id:'urban-sketching',label:'Urban sketching',tags:['creative','city']},{id:'fermentation',label:'Fermentation',tags:['food','craft']},{id:'community-gardening',label:'Community gardening',tags:['outdoors','community']},{id:'amateur-astronomy',label:'Amateur astronomy',tags:['science','outdoors']},{id:'archive-diving',label:'Archive diving',tags:['history','research']},{id:'bouldering',label:'Bouldering',tags:['movement','outdoors']},{id:'zine-making',label:'Zine making',tags:['creative','community']},{id:'language-exchange',label:'Language exchange',tags:['community','travel']},{id:'birdwatching',label:'Birdwatching',tags:['nature','outdoors']},{id:'analog-photography',label:'Analog photography',tags:['creative','visual']}
];
const WILDCARDS=['Mushroom cultivation','Competitive puzzle solving','Night swimming','Restoring old radios','Experimental cooking','Local history walks','Origami engineering','Volunteering at a repair café'].map((label,index)=>({id:`wildcard-${index}`,label,tags:['wildcard']}));
const personalityDefaults={traits:['curious','thoughtful'],dimensions:{openness:0.72,empathy:0.68,energy:0.55,conscientiousness:0.6},voice:'Observant and warm',motivations:['understand how things work','make room for other perspectives'],contradictions:['careful with trust, quick to notice possibility']};
const styleInterestSignals={"tech-girlie":['technology','creative'],booktok:['creative','research'],streetwear:['city','community']};

export function normalizePersonality(personality={}){const legacy=Array.isArray(personality.traits)?personality.traits:[];return {...personalityDefaults,...clone(personality),traits:legacy.length?legacy:personalityDefaults.traits,dimensions:{...personalityDefaults.dimensions,...(personality.dimensions||{})},motivations:Array.isArray(personality.motivations)&&personality.motivations.length?personality.motivations:personalityDefaults.motivations,contradictions:Array.isArray(personality.contradictions)&&personality.contradictions.length?personality.contradictions:personalityDefaults.contradictions};}

export function suggestInterests(state,{seed='promptforge-1',limit=6}={}){const existing=state.character?.interests||state.interestState?.characterInterests||[];const tokens=new Set([...(state.interestState?.activeContext||[]),...(state.scene?.tags||[]),norm(state.scene?.activity),norm(state.scene?.location)]);const packs=(state.styleMix?.influences||[]).flatMap(item=>{const pack=STYLE_PACKS[item.packId];return Object.values(pack?.atoms||{}).flat().map(atom=>({id:atom.id,label:atom.value,tags:['style']}))});const likely=pick(INTERESTS.filter(item=>item.tags.some(tag=>tokens.has(tag))),seed,1).slice(0,Math.max(1,Math.floor(limit/3)));const adjacent=pick(INTERESTS.filter(item=>!likely.includes(item)),seed,2).slice(0,Math.max(1,Math.floor(limit/3)));const wildcard=pick(WILDCARDS,seed,3).slice(0,Math.max(1,Math.floor(limit/3)));const mixed=unique([...likely,...adjacent,...wildcard,...pick(packs,seed,4)],existing);return mixed.slice(0,limit).map(item=>({...item,kind:item.tags?.includes('wildcard')?'wildcard':likely.includes(item)?'likely':'adjacent'}));}

export function generatePersonality(state,{seed='promptforge-1'}={}){const base=normalizePersonality(state.character?.personality);const n=seedHash(`${seed}|personality`);const variants=[['Pattern-seeking','gentle skeptic'],['Playful precision','quietly stubborn'],['Restless curiosity','protective loyalty'],['Measured intensity','unexpected tenderness']];const pair=variants[n%variants.length];return {...base,traits:unique([...base.traits,...pair]),voice:base.voice||'Observant and warm',motivations:unique([...base.motivations,pair[0].toLowerCase()]),contradictions:unique([...base.contradictions,pair[1]])};}

export const WARDROBE_SLOTS=['head','top','bottom','onePiece','shoes','outerwear','accessory'];
export function normalizeWardrobe(wardrobe={}){const slots=wardrobe.slots||{};return {...wardrobe,source:wardrobe.source||'resolved',items:Array.isArray(wardrobe.items)?wardrobe.items:[],slots:Object.fromEntries(WARDROBE_SLOTS.map(slot=>[slot,slots[slot]||'']))};}
export function suggestWardrobePieces(state,{seed='promptforge-1'}={}){const wardrobe=normalizeWardrobe(state.wardrobe);const resolved=state.resolvedDirectorState?.resolved?.wardrobe||[];const suggestions={};for(const slot of WARDROBE_SLOTS)if(!wardrobe.slots[slot])suggestions[slot]=resolved[slot]||pick(['textured knit layer','relaxed trousers','minimal sneakers','utility overshirt','silk scarf'],seed,slot.length)[0];return suggestions;}
